const docs = $input.first().json.results || [];
const alerts = [];
const now = new Date();
for (const doc of docs) {
  // Check custom fields for expiry date (stored as metadata)
  if (doc.custom_fields) {
    for (const field of doc.custom_fields) {
      if (field.name === 'expiry_date' && field.value_date) {
        const expiry = new Date(field.value_date);
        const daysUntil = Math.ceil((expiry - now) / (1000 * 60 * 60 * 24));
        if (daysUntil <= 30 && daysUntil >= 0) {
          alerts.push({
            json: {
              doc_id: doc.id,
              title: doc.title,
              expiry_date: field.value_date,
              days_remaining: daysUntil,
              urgency: daysUntil <= 7 ? 'HIGH' : 'WARNING'
            }
          });
        }
      }
    }
  }
}
return alerts.length ? alerts : [{ json: { message: 'No expiring documents' } }];

